// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext;

import static org.assertj.core.api.Assertions.assertThat;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.VF;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.assertEvaluationError;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.date;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.dt;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.dur;

import java.util.List;

import org.eclipse.rdf4j.model.Literal;
import org.junit.jupiter.api.Test;

/**
 * Edge cases of {@code dtf:dateBin(stride, dt [, origin])}.
 */
class DateBinEdgeCaseTest {

	private final DateBin dateBin = new DateBin();

	@Test
	void dayMinuteAndMonthStridesBinFromTheDefaultOrigin() {
		assertThat(dateBin.evaluate(VF, dur("P1D"), dt("2024-05-17T10:41:12Z"))).isEqualTo(dt("2024-05-17T00:00:00Z"));
		assertThat(dateBin.evaluate(VF, dur("PT15M"), dt("2024-05-17T10:44:59.999Z")))
				.isEqualTo(dt("2024-05-17T10:30:00Z"));
		assertThat(dateBin.evaluate(VF, dur("P1M"), dt("2024-05-17T10:41:12Z")))
				.isEqualTo(dt("2024-05-01T00:00:00Z"));
	}

	@Test
	void negativeStrideIsAnEvaluationError() {
		for (String stride : List.of("-PT15M", "-P1D", "-P1M", "-P1Y")) {
			assertEvaluationError(stride, () -> dateBin.evaluate(VF, dur(stride), dt("2024-05-17T10:41:12Z")));
		}
	}

	@Test
	void valuesBeforeTheOriginRoundDownNotTowardsZero() {
		// 23:50 is 10 minutes before the origin; the bin is [23:45, 00:00), not [23:50, 00:05)
		assertThat(dateBin.evaluate(VF, dur("PT15M"), dt("1999-12-31T23:50:00")))
				.isEqualTo(dt("1999-12-31T23:45:00"));
		// two months before the origin with a quarter stride: the bin starts at 1999-10-01, not 1999-11-01
		assertThat(dateBin.evaluate(VF, dur("P3M"), date("1999-11-15"))).isEqualTo(date("1999-10-01"));
		assertThat(dateBin.evaluate(VF, dur("P1M"), date("1999-11-15"))).isEqualTo(date("1999-11-01"));
	}

	@Test
	void valueExactlyOnABinEdgeMapsToThatEdge() {
		assertThat(dateBin.evaluate(VF, dur("PT15M"), dt("2024-05-17T10:30:00Z")))
				.isEqualTo(dt("2024-05-17T10:30:00Z"));
		assertThat(dateBin.evaluate(VF, dur("P1M"), dt("2024-05-01T00:00:00Z"))).isEqualTo(dt("2024-05-01T00:00:00Z"));
		assertThat(dateBin.evaluate(VF, dur("P1D"), dt("1999-12-31T00:00:00"))).isEqualTo(dt("1999-12-31T00:00:00"));
		Literal origin = dt("2024-05-17T10:07:00Z");
		assertThat(dateBin.evaluate(VF, dur("PT15M"), origin, origin)).isEqualTo(origin);
	}

	@Test
	void originTimezoneIsIgnoredAndTheValueKeepsItsOwnTimezone() {
		// pins current behaviour: dateBin works on local clock values (PostgreSQL date_bin semantics), so the
		// origin's timezone does not shift the bins and the result carries the timezone of dt
		assertThat(dateBin.evaluate(VF, dur("PT1H"), dt("2024-05-17T10:30:00+02:00"), dt("2024-05-17T00:15:00Z")))
				.isEqualTo(dt("2024-05-17T10:15:00+02:00"));
		assertThat(dateBin.evaluate(VF, dur("PT1H"), dt("2024-05-17T10:30:00+02:00"),
				dt("2024-05-17T00:15:00-05:00"))).isEqualTo(dt("2024-05-17T10:15:00+02:00"));
	}

	@Test
	void zeroStrideIsAnEvaluationError() {
		for (String stride : List.of("PT0S", "P0M", "P0D", "P0Y0M0DT0H0M0S")) {
			assertEvaluationError(stride, () -> dateBin.evaluate(VF, dur(stride), dt("2024-05-17T10:41:12Z")));
		}
	}

	@Test
	void mixedMonthAndDayTimeStridesAreAnEvaluationError() {
		// pins current behaviour: a stride must be either month-based or day/time-based, never both
		for (String stride : List.of("P1Y1D", "P1MT1S", "P1Y2M3DT4H")) {
			assertEvaluationError(stride, () -> dateBin.evaluate(VF, dur(stride), dt("2024-05-17T10:41:12Z")));
		}
	}
}
